FUNCTION_BLOCK FB_P10
VAR_INPUT
    TemperatureSensorInput : REAL;
    SetTemperature : REAL;
END_VAR
VAR_OUTPUT
    CurrentTemperature : REAL;
    SetTempDisplay : REAL;
    HeaterStatus : BOOL;
    OverheatProtection : BOOL;
    HeaterOutput : BOOL;
END_VAR
VAR
    FirstScan : BOOL := TRUE;
    SensorFault : BOOL := FALSE;
    SensorFaultPrev : BOOL := FALSE;
    HeaterOnTimer : INT := 0;
    OverheatHoldTimer : INT := 0;
END_VAR

CurrentTemperature := TemperatureSensorInput;
SetTempDisplay := SetTemperature;

IF FirstScan THEN
    HeaterOutput := FALSE;
    HeaterStatus := FALSE;
    OverheatProtection := FALSE;
    HeaterOnTimer := 0;
    OverheatHoldTimer := 0;
    SensorFault := (TemperatureSensorInput < 0.0) OR (TemperatureSensorInput > 100.0);
    SensorFaultPrev := SensorFault;
    FirstScan := FALSE;
ELSE
    SensorFault := (TemperatureSensorInput < 0.0) OR (TemperatureSensorInput > 100.0);

    IF OverheatProtection THEN
        HeaterOutput := FALSE;
        IF OverheatHoldTimer > 150 THEN
            OverheatProtection := FALSE;
            OverheatHoldTimer := 0;
        ELSE
            OverheatHoldTimer := OverheatHoldTimer + 1;
        END_IF;
    ELSE
        IF SensorFault OR SensorFaultPrev THEN
            HeaterOutput := FALSE;
            HeaterOnTimer := 0;
        ELSIF TemperatureSensorInput < SetTemperature THEN
            IF HeaterOnTimer >= 250 THEN
                OverheatProtection := TRUE;
                HeaterOutput := FALSE;
                HeaterOnTimer := 0;
                OverheatHoldTimer := 1;
            ELSE
                HeaterOutput := TRUE;
                HeaterOnTimer := HeaterOnTimer + 1;
            END_IF;
        ELSE
            HeaterOutput := FALSE;
            HeaterOnTimer := 0;
        END_IF;
    END_IF;

    SensorFaultPrev := SensorFault;
    HeaterStatus := HeaterOutput;
END_IF;

END_FUNCTION_BLOCK
